import remarkGfm from "remark-gfm";
import { mergeConfig } from "vite";
import svgr from "vite-plugin-svgr";

/** @type { import('@storybook/react-vite').StorybookConfig } */
export default {
  staticDirs: ["../public", "../dist/css"],

  stories: [
    "../src/elements/**/*.doc.mdx",
    "../src/elements/**/*.stories.jsx",
    "../src/doc/*.mdx",
    "../src/doc/*.stories.jsx",
  ],

  framework: {
    name: "@storybook/react-vite",
    options: {},
  },

  core: {
    disableTelemetry: true, // Disables telemetry
  },

  addons: [
    {
      name: "@storybook/addon-essentials",
      options: {
        // We disable the built-in docs configuration here so we can
        // manually add @storybook/addon-docs with remarkGfm below.
        docs: false,
      },
    },
    "@storybook/addon-links",
    "@storybook/addon-a11y",
    "@storybook/addon-themes",
    "@airbus/storybook-addon-posthog",
    {
      name: "@storybook/addon-docs",
      options: {
        mdxPluginOptions: {
          mdxCompileOptions: {
            // Enables GitHub Flavored Markdown (tables, strikethrough, etc.)
            remarkPlugins: [remarkGfm],
          },
        },
      },
    },
  ],

  docs: {
    // Use 'autodocs' to enable auto-generated docs for stories without MDX files.
    // Set to true to enable for all, or 'tag' to enable only for stories with tags: ['autodocs']
    autodocs: "tag",
    defaultName: "docs",
  },

  viteFinal: async (config) => {
    return mergeConfig(config, {
      plugins: [svgr()],
      build: {
        // Fix for Storybook issue https://github.com/storybookjs/storybook/issues/22223 regarding top-level await/esnext features
        target: "esnext",
      },
    });
  },
};
